using System.ComponentModel;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Tool implementations ---

var notes = new ResearchNotes();

var tools = new List<AITool>
{
    AIFunctionFactory.Create(
        (string query) =>
        {
            Console.WriteLine($"  🔍 Searching: \"{query}\"");
            return WebSearcher.SearchAsync(query);
        },
        "web_search",
        "Searches the web for the given query and returns a list of result snippets. Use this to find information on a topic."),

    AIFunctionFactory.Create(
        ([Description("A concise note capturing a key finding")] string note) =>
        {
            notes.Add(note);
            Console.WriteLine($"  📝 Noted: {note[..Math.Min(note.Length, 80)]}...");
            return "Note saved.";
        },
        "take_note",
        "Saves a research note. Call this whenever you find an important fact or insight worth remembering."),

    AIFunctionFactory.Create(
        () => notes.GetAll(),
        "read_notes",
        "Returns all notes taken so far. Use this to review what you've already learned before writing a summary."),
};

// --- Chat client setup ---

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? throw new InvalidOperationException(
    "Set the OPENAI_API_KEY environment variable.");
var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

IChatClient client = new OpenAIClient(apiKey)
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

// --- Agent loop ---

Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\n🤖 Researching \"{topic}\"...\n");

var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your goal is to thoroughly research the topic the user provides.

        Follow this process:
        1. Search the web 2-3 times with different queries to gather broad information.
        2. After each search, take notes on the key findings using the take_note tool.
        3. After gathering enough information, read your notes with read_notes.
        4. Write a well-structured summary with sections, citing what you learned.

        Be thorough but concise. Always use your tools — do not make up information.
        """),
    new(ChatRole.User, $"Please research this topic: {topic}"),
};

var response = await client.GetResponseAsync(messages, new ChatOptions { Tools = tools });

Console.WriteLine("\n════════════════════════════════════════");
Console.WriteLine("📋 RESEARCH SUMMARY");
Console.WriteLine("════════════════════════════════════════\n");
Console.WriteLine(response.Text);

// --- Helper types ---

class ResearchNotes
{
    private readonly List<string> _notes = [];

    public void Add(string note) => _notes.Add(note);

    public string GetAll() =>
        _notes.Count == 0
            ? "No notes taken yet."
            : string.Join("\n", _notes.Select((n, i) => $"{i + 1}. {n}"));
}

static class WebSearcher
{
    private static readonly HttpClient Http = new();

    public static async Task<string> SearchAsync(string query)
    {
        // Uses the free DuckDuckGo instant-answer API as a lightweight search proxy
        var url = $"https://html.duckduckgo.com/html/?q={Uri.EscapeDataString(query)}";
        Http.DefaultRequestHeaders.UserAgent.Clear();
        Http.DefaultRequestHeaders.UserAgent.ParseAdd(
            "Mozilla/5.0 (ResearchAgent/1.0)");

        try
        {
            var html = await Http.GetStringAsync(url);
            return ParseSnippets(html);
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    private static string ParseSnippets(string html)
    {
        var results = new List<string>();
        var snippetTag = "class=\"result__snippet\"";
        var idx = 0;

        while (results.Count < 6 && (idx = html.IndexOf(snippetTag, idx, StringComparison.Ordinal)) != -1)
        {
            idx = html.IndexOf('>', idx) + 1;
            var end = html.IndexOf('<', idx);
            if (end > idx)
            {
                var text = System.Net.WebUtility.HtmlDecode(html[idx..end]).Trim();
                if (text.Length > 20)
                    results.Add(text);
            }
        }

        return results.Count > 0
            ? string.Join("\n\n", results.Select((r, i) => $"[{i + 1}] {r}"))
            : "No results found. Try a different query.";
    }
}

