+static class WebSearcher
+{
+    private static readonly HttpClient Http = new();
+
+    public static async Task<string> SearchAsync(string query)
+    {
+        // Uses the free DuckDuckGo instant-answer API as a lightweight search proxy
+        var url = $"https://html.duckduckgo.com/html/?q={Uri.EscapeDataString(query)}";
+        Http.DefaultRequestHeaders.UserAgent.Clear();
+        Http.DefaultRequestHeaders.UserAgent.ParseAdd(
+            "Mozilla/5.0 (ResearchAgent/1.0)");
+
+        try
+        {
+            var html = await Http.GetStringAsync(url);
+            return ParseSnippets(html);
+        }
+        catch (Exception ex)
+        {
+            return $"Search failed: {ex.Message}";
+        }
+    }
+
+    private static string ParseSnippets(string html)
+    {
+        var results = new List<string>();
+        var snippetTag = "class=\"result__snippet\"";
+        var idx = 0;
+
+        while (results.Count < 6 && (idx = html.IndexOf(snippetTag, idx, StringComparison.Ordinal)) != -1)
+        {
+            idx = html.IndexOf('>', idx) + 1;
+            var end = html.IndexOf('<', idx);
+            if (end > idx)
+            {
+                var text = System.Net.WebUtility.HtmlDecode(html[idx..end]).Trim();
+                if (text.Length > 20)
+                    results.Add(text);
+            }
+        }
+
+        return results.Count > 0
+            ? string.Join("\n\n", results.Select((r, i) => $"[{i + 1}] {r}"))
+            : "No results found. Try a different query.";
+    }
+}
